mapper.sql:
FROM appointment a
LEFT JOIN gate_lane l ON l.id = a.lane_id
LEFT JOIN eir_order e ON e.id = a.eir_id
LEFT JOIN transport_company c ON c.id = e.company_id
LEFT JOIN (

    SELECT gcl.appointment_id,
           SUM(CASE WHEN gcl.result = 'PASS' AND (gcl.remark IS NULL OR gcl.remark NOT LIKE '%重复核验%')
                    THEN 1 ELSE 0 END) AS pass_cnt,
           SUM(CASE WHEN gcl.result = 'FAIL' THEN 1 ELSE 0 END) AS fail_cnt
    FROM gate_check_log gcl
    JOIN appointment a2 ON a2.id = gcl.appointment_id
    WHERE a2.appt_date BETWEEN #{q.startDate} AND #{q.endDate}
    GROUP BY gcl.appointment_id
) g ON g.appointment_id = a.id
WHERE a.appt_date BETWEEN #{q.startDate} AND #{q.endDate}

    AND a.lane_id = #{q.laneId}


    AND a.time_slot = #{q.timeSlot}


    AND e.company_id = #{q.companyId}
